import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { buildSeoPagesMeta } from '../scripts/generate-seo-pages-meta.mjs';

// The light metadata file must be exactly seoPages.json minus `html` (regenerated by `npm run build`).
test('seoPagesMeta.json matches seoPages.json without html', () => {
  const full = JSON.parse(readFileSync('src/content/seoPages.json', 'utf8'));
  const meta = JSON.parse(readFileSync('src/content/seoPagesMeta.json', 'utf8'));
  assert.deepEqual(meta, buildSeoPagesMeta(full), 'run: node scripts/generate-seo-pages-meta.mjs');
  assert.ok(meta.every((page: Record<string, unknown>) => !('html' in page)));
});

// The app shell must not import the full SEO pages (with ~0.5 MB of article HTML).
test('app shell, router and head metadata use the light SEO metadata', () => {
  for (const file of ['src/App.tsx', 'src/i18n/routing.ts', 'src/i18n/content/index.ts', 'src/lib/routeMetadata.ts']) {
    assert.doesNotMatch(readFileSync(file, 'utf8'), /from ['"][./]*(?:lib\/)?seoPages['"]/, file);
  }
  assert.match(readFileSync('src/App.tsx', 'utf8'), /lazy\(\(\) =>\s*import\('\.\/components\/SearchInsightsPage'\)/);
});
